"""Enumerate the semantics of a small argumentation framework."""
from __future__ import annotations
from itertools import combinations
from typing import FrozenSet, List, Set, Tuple

Relation = Set[Tuple[int, int]]


def is_conflict_free(R: Relation, S: FrozenSet[int]) -> bool:
    return not any((a, b) in R for a in S for b in S)


def defends(R: Relation, S: FrozenSet[int], a: int) -> bool:
    for b in {x for (x, y) in R if y == a}:
        if not any((c, b) in R for c in S):
            return False
    return True


def is_admissible(R: Relation, S: FrozenSet[int]) -> bool:
    return is_conflict_free(R, S) and all(defends(R, S, a) for a in S)


def powerset(A: FrozenSet[int]) -> List[FrozenSet[int]]:
    xs = list(A)
    return [frozenset(c) for r in range(len(xs) + 1) for c in combinations(xs, r)]


def preferred(R: Relation, A: FrozenSet[int]) -> List[FrozenSet[int]]:
    adm = [S for S in powerset(A) if is_admissible(R, S)]
    return [S for S in adm if not any(S < T for T in adm)]


if __name__ == "__main__":
    # Symmetric 4-cycle 0-1-2-3-0.
    A = frozenset(range(4))
    edges = [(0, 1), (1, 2), (2, 3), (3, 0)]
    R = {e for e in edges} | {(b, a) for (a, b) in edges}
    print("preferred extensions:", [sorted(s) for s in preferred(R, A)])

"""Survey the Euler bridge across complete conflict graphs."""
from __future__ import annotations
from itertools import combinations
from typing import FrozenSet, List, Set, Tuple

Relation = Set[Tuple[int, int]]


def is_conflict_free(R: Relation, S: FrozenSet[int]) -> bool:
    return not any((a, b) in R for a in S for b in S)


def powerset(A: FrozenSet[int]) -> List[FrozenSet[int]]:
    xs = list(A)
    return [frozenset(c) for r in range(len(xs) + 1) for c in combinations(xs, r)]


def euler_characteristic(faces: List[FrozenSet[int]]) -> int:
    return sum((-1) ** (len(s) - 1) for s in faces if s)


def complete(n: int) -> Tuple[FrozenSet[int], Relation]:
    A = frozenset(range(n))
    R = {(a, b) for a in range(n) for b in range(n) if a != b}
    return A, R


if __name__ == "__main__":
    for n in range(0, 8):
        A, R = complete(n)
        faces = [S for S in powerset(A) if is_conflict_free(R, S)]
        chi = euler_characteristic(faces)
        npref = sum(1 for S in faces if len(S) == 1)  # singletons for n>=1
        print(f"n={n}: chi={chi}, #preferred={max(npref, 1 if n==0 else npref)}")

"""Compute the grounded extension by iterating the defense operator."""
from __future__ import annotations
from typing import FrozenSet, Set, Tuple

Relation = Set[Tuple[int, int]]


def defends(R: Relation, S: FrozenSet[int], a: int) -> bool:
    for b in {x for (x, y) in R if y == a}:
        if not any((c, b) in R for c in S):
            return False
    return True


def defense_operator(R: Relation, A: FrozenSet[int],
                     S: FrozenSet[int]) -> FrozenSet[int]:
    return frozenset(a for a in A if defends(R, S, a))


def grounded(R: Relation, A: FrozenSet[int]) -> FrozenSet[int]:
    S: FrozenSet[int] = frozenset()
    trace = [S]
    while True:
        nxt = defense_operator(R, A, S)
        trace.append(nxt)
        if nxt == S:
            return S
        S = nxt


if __name__ == "__main__":
    # 0 unattacked, 1<->2 mutual, 1<->3 mutual (symmetric).
    A = frozenset(range(4))
    R = {(1, 2), (2, 1), (1, 3), (3, 1)}
    print("grounded extension:", sorted(grounded(R, A)))

